//! Linting for Django/Jinja templates.
//!
//! This crate provides lint rules for HTML templates with Django/Jinja syntax.
//! Its rules read the AST generated by `markup_fmt`, or Django's token stream for the tags.
//!
//! # Example
//!
//! ```
//! use djangofmt_lint::{lint_source, Settings};
//! use markup_fmt::Language;
//!
//! let source = r#"<form method="put"></form>"#;
//! let outcome = lint_source(source, Language::Jinja, &[], &Settings::default(), None);
//! assert_eq!(outcome.diagnostics.len(), 1);
//! ```

